// Compute the minimal nonnegative distance from n to a multiple of k.
#[requires(n >= 0)]        // only make sense when n is nonnegative
#[requires(k >  0)]        // k must be positive
#[ensures(result >= 0)]    // result is nonnegative
// result is at most r = n % k
#[ensures(result <= (n % k))]
// result is at most dr = k - (n % k)
#[ensures(result <= (k - (n % k)))]
// and it is exactly one of those two distances
#[ensures(result == (n % k) || result == (k - (n % k)))]
fn solve(n: i8, k: i8) -> i8 {
    // r is the nonnegative Rust remainder of n / k
    let r = n % k;
    // prove r is in [0, k)
    assert!(r >= 0);
    assert!(r < k);

    // dr is the “up‐distance” from n to the next multiple of k
    let dr = k - r;
    // dr is in (0, k]
    assert!(dr >  0);
    assert!(dr <= k);

    // take the minimum of the two distances
    let res = std::cmp::min(r, dr);
    // discharge the rest of the ensures:
    assert!(res >= 0);
    assert!(res <= r);
    assert!(res <= dr);
    assert!(res == r || res == dr);

    res
}

